"""Educational flight-control laws for the point-mass fighter."""

from __future__ import annotations

from dataclasses import dataclass
import math

from .dynamics import (
    AircraftParams,
    PointMassState,
    RawControl,
    clamp,
    drag_force,
    wrap_angle,
    G,
)


@dataclass(frozen=True)
class ControlCommand:
    """Autopilot-level command generated by the control system."""

    throttle: float
    load_factor: float
    bank: float
    target_gamma: float
    target_heading: float

    def raw(self) -> RawControl:
        return RawControl(self.throttle, self.load_factor, self.bank)


class FlightControlSystem:
    """Simple control-augmentation system.

    The loops are intentionally readable:
    - speed error sets throttle;
    - vertical-speed or flight-path error sets normal load factor;
    - heading or lateral offset sets bank;
    - envelope protection clips the final commands.
    """

    def __init__(self, params: AircraftParams | None = None) -> None:
        self.params = params or AircraftParams()
        self.params.validate()
        self._previous_throttle = 0.5

    def envelope_protect(
        self,
        state: PointMassState,
        throttle: float,
        load_factor: float,
        bank: float,
    ) -> tuple[float, float, float]:
        """Apply hard teaching-model limits."""

        p = self.params
        throttle = clamp(throttle, 0.0, 1.0)
        max_rate = p.max_throttle_rate
        throttle = clamp(
            throttle,
            self._previous_throttle - max_rate * 0.02,
            self._previous_throttle + max_rate * 0.02,
        )
        self._previous_throttle = throttle

        # Low speed margin shrinks the allowable manoeuvre demand.
        speed_margin = clamp(
            (state.speed - p.min_speed) / max(1.0, 0.35 * p.min_speed),
            0.25,
            1.0,
        )
        load_factor = clamp(
            load_factor,
            p.min_load_factor * speed_margin,
            p.max_load_factor * speed_margin,
        )
        bank = clamp(bank, -p.max_bank * speed_margin, p.max_bank * speed_margin)
        return throttle, load_factor, bank

    def command(
        self,
        state: PointMassState,
        target_speed: float,
        target_gamma: float = 0.0,
        target_heading: float | None = None,
        max_bank: float | None = None,
    ) -> ControlCommand:
        """Build a protected command from speed, climb-angle and heading targets."""

        p = self.params
        target_speed = clamp(target_speed, p.min_speed, p.max_speed)
        target_gamma = clamp(target_gamma, math.radians(-20.0), math.radians(20.0))
        if target_heading is None:
            target_heading = state.heading
        heading_error = wrap_angle(target_heading - state.heading)

        speed_error = target_speed - state.speed
        equilibrium_drag = drag_force(state, p, 1.0)
        equilibrium_throttle = equilibrium_drag / p.max_thrust
        throttle = equilibrium_throttle + 0.012 * speed_error

        gamma_error = target_gamma - state.gamma
        load_factor = math.cos(state.gamma) + 5.0 * gamma_error
        bank_limit = p.max_bank if max_bank is None else min(p.max_bank, abs(max_bank))
        bank = clamp(1.8 * heading_error, -bank_limit, bank_limit)

        throttle, load_factor, bank = self.envelope_protect(
            state, throttle, load_factor, bank
        )
        return ControlCommand(
            throttle=throttle,
            load_factor=load_factor,
            bank=bank,
            target_gamma=target_gamma,
            target_heading=target_heading,
        )

    def takeoff_rotation_command(self, state: PointMassState) -> ControlCommand:
        """Command initial rotation and a stable climb after liftoff."""

        return self.command(
            state,
            target_speed=max(90.0, state.speed + 8.0),
            target_gamma=math.radians(8.0),
            target_heading=state.heading,
            max_bank=math.radians(5.0),
        )

    def altitude_hold_command(
        self,
        state: PointMassState,
        target_altitude: float,
        target_speed: float,
        target_heading: float,
    ) -> ControlCommand:
        """Capture and hold altitude with a shallow flight-path target."""

        altitude_error = target_altitude - state.z
        target_vertical_speed = clamp(0.8 * altitude_error, -8.0, 8.0)
        target_gamma = math.asin(
            clamp(target_vertical_speed / max(state.speed, 1.0), -0.25, 0.25)
        )
        return self.command(
            state,
            target_speed=target_speed,
            target_gamma=target_gamma,
            target_heading=target_heading,
        )

    def carrier_approach_command(
        self,
        state: PointMassState,
        desired_altitude: float,
        lateral_error: float,
        approach_speed: float,
    ) -> ControlCommand:
        """Command glidepath and line-up corrections for a fixed carrier deck."""

        altitude_error = desired_altitude - state.z
        target_vertical_speed = clamp(0.55 * altitude_error - 3.2, -6.0, 2.0)
        target_gamma = math.asin(
            clamp(target_vertical_speed / max(state.speed, 1.0), -0.18, 0.08)
        )
        # Heading correction is proportional to line-up error, limited to a few degrees.
        target_heading = clamp(-0.012 * lateral_error, math.radians(-12.0), math.radians(12.0))
        return self.command(
            state,
            target_speed=approach_speed,
            target_gamma=target_gamma,
            target_heading=target_heading,
            max_bank=math.radians(15.0),
        )
